  journey.innerHTML=`<div class="drive-sticky"><div class="drive-copy"><span class="eyebrow">DE LA PRIMERA MIRADA AL PRÓXIMO DESTINO</span><h2 id="drive-title">Hay caminos que<br><em>empiezan contigo.</em></h2><p>Sigue bajando. Tu próximo capítulo está más cerca.</p></div><div class="drive-landscape" aria-hidden="true"><svg viewBox="0 0 1200 500" class="drive-road"><defs><linearGradient id="road-fill" x2="0" y2="1"><stop stop-color="#242a30"/><stop offset="1" stop-color="#11171c"/></linearGradient><linearGradient id="body-paint" x2="1" y2="1"><stop stop-color="#eeeeef"/><stop offset=".48" stop-color="#9fa7ae"/><stop offset="1" stop-color="#e3e7ea"/></linearGradient><linearGradient id="light-beam"><stop stop-color="#d7e9ff" stop-opacity=".28"/><stop offset="1" stop-color="#d7e9ff" stop-opacity="0"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="4"/></filter></defs><path class="terrain-line" d="M-50 150 Q230 10 520 170T1250 110M-50 430 Q280 230 600 390T1250 320"/><path class="road-shadow" d="M-100 350 C190 350 230 120 520 200 S900 430 1300 150"/><path class="road-edge" d="M-100 350 C190 350 230 120 520 200 S900 430 1300 150"/><path class="road-surface" d="M-100 350 C190 350 230 120 520 200 S900 430 1300 150"/><path class="road-center" d="M-100 350 C190 350 230 120 520 200 S900 430 1300 150"/><path id="drive-route" d="M-100 334 C190 334 230 104 520 184 S900 414 1300 134" fill="none" stroke="none"/><g id="driving-car"><ellipse cx="0" cy="8" rx="57" ry="24" fill="#000" opacity=".7"/><path d="M43-14 170-45 170 45 43 14Z" fill="url(#light-beam)"/><rect x="-28" y="-24" width="20" height="8" rx="3" fill="#050708"/><rect x="21" y="-24" width="20" height="8" rx="3" fill="#050708"/><rect x="-28" y="16" width="20" height="8" rx="3" fill="#050708"/><rect x="21" y="16" width="20" height="8" rx="3" fill="#050708"/><path d="M-44-17 Q-49 0-44 17 L32 20 Q51 18 52 0 Q51-18 32-20Z" fill="url(#body-paint)" stroke="#f2f4f5" stroke-width="1"/><path d="M-12-16 4-17 17-14 17 14 4 17-12 16Z" fill="#141e28"/><path d="M-33-14-23-16-20 16-33 14Z" fill="#101a24"/><rect x="-20" y="-14" width="18" height="28" rx="3" fill="#7a848d"/><path d="M23-16 39-13M23 16 39 13" stroke="#73808a"/><rect x="45" y="-14" width="5" height="8" rx="2" fill="#e7f6ff"/><rect x="45" y="6" width="5" height="8" rx="2" fill="#e7f6ff"/><rect x="-46" y="-15" width="4" height="8" rx="1" fill="#ff1637"/><rect x="-46" y="7" width="4" height="8" rx="1" fill="#ff1637"/><path d="M-51-15-90-15M-51 15-90 15" stroke="#ed1232" stroke-width="3" opacity=".35"/></g></svg></div><div class="drive-bottom"><span>TORRES GARAGE</span><div class="drive-progress"><i></i></div><span>ENCUENTRA EL TUYO</span></div><a class="drive-skip" href="#vehiculos">Explorar el catálogo</a></div>`;
