  function resetIntro(){if(introAnimating)return;clearTimeout(introTimer);lastIntroReset=performance.now();const returning=introDismissed||introStage.getBoundingClientRect().top<-24;if(returning&&!introDismissed){introStage.classList.add('is-dismissed');void hero.offsetHeight;}introDismissed=false;introAnimating=returning;wheelIntent=0;hero.inert=returning;journey.inert=true;if(returning)turnDuringTransition(-1);introStage.classList.remove('is-dismissed');history.replaceState(null,'','#inicio');window.scrollTo({top:scrollY+introStage.getBoundingClientRect().top,behavior:'instant'});if(returning)introTimer=setTimeout(finishIntro,reduced.matches?0:1050);requestDrive();}
